import unittest

import mylib as m


class T(unittest.TestCase):
    def test_unique_sorted_hidden(self):
        self.assertEqual(m.unique_sorted([]), [])
        self.assertEqual(m.unique_sorted([5, 5]), [5])

    def test_is_palindrome_hidden(self):
        self.assertTrue(m.is_palindrome(''))
        self.assertFalse(m.is_palindrome('ab'))

    def test_count_vowels_hidden(self):
        self.assertEqual(m.count_vowels(''), 0)
        self.assertEqual(m.count_vowels('xyz'), 0)

    def test_count_even_hidden(self):
        self.assertEqual(m.count_even([]), 0)
        self.assertEqual(m.count_even([0, -2, 3]), 2)


if __name__ == '__main__':
    unittest.main()
